#include "ChemistrySimulation.h"
#include "WorldCore/ChunkState.h"
void UChemistrySimulation::SimulateChunk(UChunkState* C,float Days){if(!C||Days<=0)return;const int32 N=FMath::RoundToInt(FMath::Sqrt((float)C->Cells.Num()));if(N<=0)return;TArray<float> New;New.SetNum(C->Cells.Num());for(int32 I=0;I<C->Cells.Num();++I){const float T=C->Cells[I].Chemistry.ToxinConcentration;float V=T*FMath::Exp(-FMath::Max(0.0f,DecayRate)*Days);const int32 X=I%N,Y=I/N;const int32 XY[4][2]={{X-1,Y},{X+1,Y},{X,Y-1},{X,Y+1}};float Sum=0;int32 Count=0;for(const auto& P:XY){if(P[0]<0||P[1]<0||P[0]>=N||P[1]>=N)continue;Sum+=C->Cells[P[1]*N+P[0]].Chemistry.ToxinConcentration;++Count;}if(Count){const float Avg=Sum/Count;V+=(Avg-T)*FMath::Clamp(DiffusionRate*Days,0.0f,0.25f);}New[I]=FMath::Clamp(V,0.0f,1.0f);}for(int32 I=0;I<New.Num();++I){C->Cells[I].Chemistry.ToxinConcentration=New[I];C->Cells[I].bHasToxin=New[I]>0.001f;C->Cells[I].bIsDirty=true;}C->MarkDirty();}
void UChemistrySimulation::ApplyToxin(UChunkState* C,int32 I,float V){if(!C||!C->Cells.IsValidIndex(I))return;FChunkCell& Cell=C->Cells[I];Cell.Chemistry.ToxinConcentration=FMath::Clamp(Cell.Chemistry.ToxinConcentration+V,0.0f,1.0f);Cell.bHasToxin=Cell.Chemistry.ToxinConcentration>0.001f;Cell.bIsDirty=true;C->MarkDirty();}
